First, let's install Three.js, a popular library for creating and manipulating 3D computer graphics in the browser using WebGL.

```bash
npm install three
```

Now, we'll create a simple EUA for controlling a 3D camera's position, rotation, and zoom using TypeScript.

1. Create a new file named `CameraController.ts`:

```typescript
import * as THREE from 'three';

class CameraController {
  private camera: THREE.PerspectiveCamera;
  private scene: THREE.Scene;
  private renderer: THREE.WebGLRenderer;

  constructor(scene: THREE.Scene, renderer: THREE.WebGLRenderer) {
    this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    this.camera.position.z = 5;

    this.scene = scene;
    this.renderer = renderer;

    // Add controls
    const controls = new THREE.OrbitControls(this.camera, this.renderer.domElement);

    this.update();
  }

  public update(): void {
    requestAnimationFrame(() => this.update());
    this.renderer.render(this.scene, this.camera);
  }
}

export default CameraController;
```

2. Use the `CameraController` class in your main TypeScript file:

```typescript
import * as THREE from 'three';
import { CameraController } from './CameraController';

// Initialize scene, renderer, and other elements...

const scene = new THREE.Scene();
const renderer = new THREE.WebGLRenderer();

const cameraController = new CameraController(scene, renderer);
```

