parameter NNZ_PER_ROW = 3; // Average number of non-zero elements per row in the parity-check matrix H
parameter WIDTH = 2 * ceil(log2(SYMBOLS)) * N; // Data width

// Define the parity-check matrix H
reg [N-1:0][NNZ_PER_ROW-1:0] H [*] {
