 Certainly! Here's a JavaScript function that uses regular expressions and string manipulation to switch the order of adjectives in a given sentence:

```javascript
function switchAdjectiveOrder(sentence) {
  // Define an array of common English adjective endings
  const adjectiveEndings = /([^ ]+ [jQUVWXZ][bs]?|[mpr]le|[lh]eavy|[dgh]old|[twrn]g|[fcs]te|[bld]y|[gnpqty]mk|[sh]arp|[sr]en|[fl]ow[er][^ ]+)/g;

  let words = sentence.split(' ');
  let newWords = [];

  // Find all adjectives and store them in a temporary array
  let adjectives = [];
  for (let i = 0; i < words.length; i++) {
    let match = adjectiveEndings.exec(words[i]);
    if (match !== null) {
      adjectives.push(words[i]);
      words.splice(i, 1);
      i--;
    }
  }

  // Reorder the adjectives and add them back to the sentence
  for (let j = adjectives.length - 1; j >= 0; j--) {
    newWords.push(adjectives[j]);
  }

  // Add the remaining non-adjective words back to the sentence
  for (let k = 0; k < words.length; k++) {
    newWords.push(words[k]);
  }

  // Join the words back into a sentence
  return newWords.join(' ') + '.';
}

// Test the function with your example sentence
console.log(switchAdjectiveOrder("Beautiful green trees are in the park.")); // "Green beautiful trees are in the park."
```

