function determineProtocol(inputData) {
  let ipVersion;
  if (inputData.sourceIP && inputData.destinationIP) { // Check if source and destination IPs are provided
    const sourceIPParts = inputData.sourceIP.split(":");
    const destIPParts = inputData.destinationIP.split(":");
     if (sourceIPParts.length > 7 || destIPParts.length > 7) { // Check if IP addresses are IPv6
      ipVersion = "IPv6";
    } else { // Assume IPv4 if IP addresses are not IPv6
      ipVersion = "IPv4";
    }
  }

  let protocol;
  if (ipVersion === "IPv6") { // Prefer IPv6 over IPv4 for IPv6-specific protocols
    if (inputData.port === 80) { // HTTP uses port 80 by default
      protocol = "HTTP over IPv6 (HTTPS uses port 443)";
    } else if (inputData.protocol === "udp") { // User explicitly specified UDP
