      Logger.log(`Could not find location for "${placeName}"`);
      continue;
    }

    const latitude = location.latLng.lat();
    const longitude = location.latLng.lng();

    sheet.getRange(i + 1, latLongColumn).setValue([latitude, longitude]);
  }
}
```

This script assumes you have already authorized the Google Maps JavaScript API for your project. To do this, go to the Google Cloud Console (https://console.cloud.google.com/) and follow the instructions there.

