```javascript
function findNestedKey(obj, strKey) {
  // Base case: if we reached a leaf node or found a match
  if (typeof obj === 'string' || obj === null || typeof obj !== 'object' || Object.keys(obj).includes(strKey)) {
    return obj === strKey ? [obj] : [];
  }

  let result = [];
  for (let key in obj) {
    const nestedResult = findNestedKey(obj[key], strKey);
    result = result.concat(...nestedResult);
  }
  return result;
}
```

