        fprintf(stderr, "Error: Please provide at least one argument.\n");
        return EXIT_FAILURE;
    }

    // Calculate the total length required by the concatenated string
    for (i = 0; i < argc; ++i) {
        total_length += strlen(argv[i]) + 1; // Add one for the space between arguments and the null terminator
    }

    // Allocate memory for the concatenated string using malloc()
    concatenated_str = (char *)malloc((total_length + (argc - 1)) * sizeof(char));
    if (!concatenated_str) { // Check if memory allocation was successful
        perror("Error allocating memory");
        return EXIT_FAILURE;
    }

    // Concatenate all the arguments into a single string
    for (i = 0; i < argc; ++i) {
        strcat(concatenated_str, argv[i]);
        if (i < argc - 1) { // Don't add a space before the last argument
            strcat(concatenated_str, " ");
        }
    }

    // Print the final concatenated string for demonstration purposes
    printf("Concatenated string: %s\n", concatenated_str);

    // Free the dynamically allocated memory and prepare for exit
    free(concatenated_str);

