```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { MiddlewareFunction, NestMiddleware } from '@nestjs/common/interfaces';

@NestMiddleware()
export class NodeEnvCheckMiddleware implements MiddlewareFunction {
  use(req: Request, res: Response, next: Function, _: Function) {
    if (process.env.NODE_ENV === 'true') {
      next();
    } else {
      res.send(false);
      res.end();
    }
  }
}

export const IsProduction = createParamDecorator((data: unknown, ctx: ExecutionContext) => {
  const request = ctx.switchToHttp().getRequest();
  return request.app.locals.isProduction;
});

@NestMiddleware()
export class NodeEnvCheckerMiddleware implements MiddlewareFunction {
  constructor(private nodeEnvCheck: NodeEnvCheckMiddleware) {}

  use(req: Request, res: Response, next: Function) {
    this.nodeEnvCheck.use(req, res, () => {
      next();
    }, this);
  }
}
```

