 To prevent the planets from being generated too close to each other, you can modify the `generateRandomPlanets` function to keep track of the minimum distances between newly generated planets and existing ones. Here's an updated version of your code:

```typescript
const generateRandomPlanets = (numPlanets, minDistance) => {
  const planets = []
  let attempts = 0
  let minDistances = new Array(3).fill().map(() => Infinity)

  while (planets.length < numPlanets && attempts < 100) {
    attempts++

    const planet = {
      position: [
        randomPosition(-30, 30),
        randomPosition(-30, 30),
        randomPosition(-30, 30),
      ],
      size: randomSize(1, 5) * scale,
      color: randomColor(),
      ringSize: 0.2 * scale,
      ringColor: randomColor(),
      ringNoise: 0.3 * scale,
    }

    // Check if planet is too close to any existing planet
    let tooClose = false

    for (let i = 0; i < planets.length; i++) {
      const distance = Math.sqrt(
        Math.pow(planet.position[0] - planets[i].position[0], 2) +
          Math.pow(planet.position[1] - planets[i].position[1], 2) +
          Math.pow(planet.position[2] - planets[i].position[2], 2)
      )

      if (distance < minDistance[0] || distance < minDistance[1] || distance < minDistance[2]) {
        tooClose = true
        break
      }

      if (i === planets.length - 1) {
        minDistances = minDistances.map((val, idx) => Math.min(val, distance))
      }
    }

    if (!tooClose) {
      planets.push(planet)
    }
  }

  return planets
}
```

